create table if not exists public.user_contacts (owner_user_id uuid not null references auth.users(id) on delete cascade, contact_user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key(owner_user_id,contact_user_id), check(owner_user_id <> contact_user_id)); alter table public.user_contacts enable row level security; grant select,insert,delete on public.user_contacts to authenticated; drop policy if exists contacts_owner_select on public.user_contacts; create policy contacts_owner_select on public.user_contacts for select to authenticated using(owner_user_id=auth.uid()); drop policy if exists contacts_owner_insert on public.user_contacts; create policy contacts_owner_insert on public.user_contacts for insert to authenticated with check(owner_user_id=auth.uid()); drop policy if exists contacts_owner_delete on public.user_contacts; create policy contacts_owner_delete on public.user_contacts for delete to authenticated using(owner_user_id=auth.uid());